fn ix(lang: &str) -> usize { match lang { "en"=>1,"de"=>2,"it"=>3,"es"=>4,_=>0 } }
pub fn weekday(lang: &str, day: usize) -> &'static str { DAYS[ix(lang)][day.min(6)] }
pub fn weekday_short(lang: &str, day: usize) -> &'static str {
    match lang {
       "en" => ["Mon","Tue","Wed","Thu","Fri","Sat","Sun"][day.min(6)],
       "de" => ["Mo.","Di.","Mi.","Do.","Fr.","Sa.","So."][day.min(6)],
       "it" => ["lun","mar","mer","gio","ven","sab","dom"][day.min(6)],
       "es" => ["lun","mar","mié","jue","vie","sáb","dom"][day.min(6)],
       _ => ["pon","uto","sri","čet","pet","sub","ned"][day.min(6)]
    }
}
pub fn month(lang: &str, month: usize) -> &'static str { MONTHS[ix(lang)][month.min(11)] }
#[cfg(test)] mod tests { use super::*;
    #[test] fn all_languages() { for c in CODES { assert!(!tr(c, "settings").is_empty()); assert!(!month(c,9).is_empty()); } }
    #[test] fn reject_unknown() { assert!(!supported("xx")); }
    #[test] fn german_short_weekdays_use_three_characters() {
        for day in 0..7 { assert_eq!(weekday_short("de",day).chars().count(), 3); }
        assert_eq!(weekday_short("de",2), "Mi.");
    }
}
